+    /// npm registry's per-version publisher metadata. When
+    /// `trusted_publisher` is present the version was published
+    /// through an OIDC-backed trusted-publisher integration, which
+    /// counts as the higher (`trustedPublisher`) trust rank that
+    /// upstream's [`getTrustEvidence`](https://github.com/pnpm/pnpm/blob/2a9bd897bf/resolving/npm-resolver/src/trustChecks.ts#L119-L127)
+    /// checks before falling back to the `provenance` attestation
+    /// rank.
+    ///
+    /// Mirrors pnpm's
+    /// [`PackageInRegistry._npmUser`](https://github.com/pnpm/pnpm/blob/2a9bd897bf/resolving/registry/types/src/index.ts#L29-L36)
+    /// (note the leading underscore on the wire).
+    #[serde(
+        default,
+        rename = "_npmUser",
+        skip_serializing_if = "Option::is_none",
+        alias = "_npm_user"
+    )]
+    pub npm_user: Option<NpmUser>,
+
+    /// Deprecation marker as served by the npm registry. The wire
+    /// value is either a string (the deprecation message), or a
+    /// boolean where `true` flags the version as deprecated without a
+    /// recorded reason and `false` means not deprecated. It is
+    /// normalized to `None` when absent, `null`, or `false`;
+    /// `Some("")` for `true`; and `Some(message)` for a string.
+    #[serde(
+        default,
+        deserialize_with = "deserialize_deprecated",
+        skip_serializing_if = "Option::is_none"
+    )]
+    pub deprecated: Option<String>,
+}
+
+/// Normalizes the npm registry's `deprecated` wire format into
+/// `Option<String>`. `null` and boolean `false` become `None`,
+/// boolean `true` becomes `Some(String::new())`, and a string is
+/// preserved as-is. Absent fields are handled by `#[serde(default)]`
+/// and never reach this function.
+fn deserialize_deprecated<'de, D>(deserializer: D) -> Result<Option<String>, D::Error>
+where
+    D: Deserializer<'de>,
+{
+    #[derive(Deserialize)]
+    #[serde(untagged)]
+    enum Deprecated {
+        Flag(bool),
+        Message(String),
+    }
+
+    Ok(match Option::<Deprecated>::deserialize(deserializer)? {
+        None | Some(Deprecated::Flag(false)) => None,
+        Some(Deprecated::Flag(true)) => Some(String::new()),
+        Some(Deprecated::Message(message)) => Some(message),
+    })
